def review(title):return '<div class="reviewbar"><span>EXIF / VISUAL REVIEW 02 / '+title+'</span><span>STATIC MOCKUP · NOT WORKING UI</span></div>'
def nav(light=False):return '<div class="nav"><img class="logo" src="assets/'+('exif-logo-light-v2.png' if light else 'exif-logo-trim.png')+'"><div class="navtools"><span>ES</span><i class="hamburger"></i></div></div>'
def page(name,body,title=None):
 (out/name).write_text('<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title or name)+'</title><link rel="stylesheet" href="artboards.css"></head><body>'+body+'</body></html>')
image03='assets/'+asset[3]
approach='<main class="approach">'+review('Approach — viewing room')+nav(True)+'''<div class="heading"><h1>Look again.</h1><p>The same photograph.<br>A different reason to look.</p></div><div class="viewing"><figure class="whole"><img src="'''+image03+'''" alt="Existing terrace photograph, full frame"><figcaption class="caption">01 / THE WHOLE FRAME</figcaption></figure><div class="detailblock"><div class="focus"><img src="'''+image03+'''" alt="Detail of chairs, slippers and linen in the same source photograph"></div><p class="caption">02 / TRACES OF USE</p><h2>Keep the signs<br>of living.</h2><p>The slippers and linen are small details. Leaving them in the frame gives an amenity photograph a more inhabited reading.</p></div></div><div class="evidence-notes"><div><span class="eyebrow">Observe</span><h3>What is visible.</h3><p>Two chairs, a table, a hammock, slippers and an unmade foreground. These are observations from the photograph.</p></div><div><span class="eyebrow">Interpret</span><h3>What it suggests.</h3><p>A place to pause, rather than an inventory of furnishings. An editorial interpretation, not a verified guest insight.</p></div><div><span class="eyebrow">Decide</span><h3>What stays.</h3><p>Retain the traces of use. Give them enough space to be noticed. Do not polish away the reason this image feels lived in.</p></div></div><div class="footer">Studio demonstration using existing photography from previous professional experience. Both frames use the same source photograph; this is not a client before/after case.</div></main>'''
page('approach.html',approach,'Approach — static composition')
work='<main class="work">'+review('What We Do — working table')+nav()+'''<div class="heading"><h1>What we do.</h1><p>See the direction.<br>See what it becomes.</p></div><div class="responsibilities"><div>Research &amp; Representation Assessment</div><div>Positioning &amp; Creative Direction</div><div>Creative Production &amp; Implementation</div></div><div class="working-table"><article class="note"><div class="docline"><span>PHOTO DIRECTION NOTE / 01</span><span>STUDIO EXERCISE</span></div><h2>Make use visible.</h2><div class="source-note"><img src="'''+image03+'''" alt="Source photograph"><p><b>Visible material</b><br>A terrace, two chairs, a hammock, slippers and linen.<br><br>The most useful detail is already in the photograph.</p></div><section><h3>The question</h3><p>Are we showing what the room has, or what it invites someone to do?</p></section><section><h3>The direction</h3><p>Lead with the pause. Preserve the slippers and linen as traces of use. Keep the natural warmth; avoid turning the frame into an amenity checklist.</p></section><section><h3>The image brief</h3><p>Leave room around the chairs. Keep the foreground. Let one short caption support the photograph rather than describe every object.</p></section><div class="docfooter">Editorial hypothesis drawn from the image. Property-specific research would establish whether this interpretation is appropriate.</div></article><div class="outputfield"><p class="eyebrow">WHAT THE DIRECTION BECOMES</p><article class="outputpage"><h2>A place to pause.</h2><img src="'''+image03+'''" alt="Image-led communication composition using the source photograph"><p>A moment of hospitality, held in one frame.</p></article><p class="objectcaption">An image brief becomes a photographic hierarchy, a short caption and a page composition. The subject stays larger than the explanation.</p></div></div><div class="work-summary"><h2>From attention<br>to something usable.</h2><p>Research establishes what can be supported. Direction chooses what should lead. Implementation carries that choice into an image brief, words and a guest-facing composition.</p></div><div class="footer">Authored studio exercise, not a commissioned property case or a claim of research results. Existing photography from previous professional experience. The brief and layout are draft editorial materials created for this review.</div></main>'''
page('what-we-do.html',work,'What We Do — static composition')
contact=review('Gallery — all 13 source photographs')+'<div class="contact-heading"><h1>The photographic edit.</h1><p>All existing sources, uncropped and ungraded. Keep nine; reserve four. Green labels identify the proposed sequence.</p></div><div class="contact-grid">'
for i in range(1,14):
 title,note=notes[i];decision='KEEP / POSITION '+str(select.index(i)+1) if i in select else 'RESERVE / NOT IN THIS EDIT'
 contact+='<article class="contact-tile"><span class="decision '+('keep' if i in select else 'reserve')+'">'+decision+'</span><div class="contact-photo"><img src="assets/'+asset[i]+'"></div><h2>'+str(i).zfill(2)+' / '+title+'</h2><p>'+note+'</p></article>'
contact+='</div>'
page('gallery-sources.html',contact,'Gallery — source evaluation')
edit=review('Gallery — proposed nine-image sequence')+'<div class="contact-heading"><h1>Reflection → presence → quiet.</h1><p>An editorial sequence across existing hospitality photographs. It does not imply a single property or a chronological day.</p></div><div class="edit-grid">'
for position,i in enumerate(select,1):
 edit+='<figure><div class="edit-photo"><img src="assets/'+asset[i]+'"></div><figcaption><span class="num">'+str(position).zfill(2)+'</span><b>'+notes[i][0]+'</b><br>Source '+str(i).zfill(2)+' · '+notes[i][1]+'</figcaption></figure>'
edit+='</div><div class="sequence-footer"><p><b>Light and color</b><br>Amber glass → white flowers → soft green → lived terrace → human presence → late light → cool foliage.</p><p><b>Scale and loop</b><br>Keep the original full-image frames and size variations. The leaves close quietly; their green and shadow connect back to the opening reflection.</p></div>'
page('gallery-edit.html',edit,'Gallery — proposed photographic edit')
film='<div class="film-row">'+''.join('<img src="assets/'+asset[i]+'">' for i in select[:4])+'</div>'
def beat(n,title,visual,copy,label='PROPOSED STATIC COMPOSITION'):
 return '<article class="beat"><div class="visual">'+visual+'</div><div class="copy"><span class="tiny">'+label+'</span><h2>'+str(n)+' / '+title+'</h2><p>'+copy+'</p></div></article>'
for option in ['a','b']:
 name='The reason to choose' if option=='a' else 'The uninterrupted arrival'
 body='<main class="story">'+review('Homepage '+option.upper())+'<div class="storyhead"><h1>'+option.upper()+' / '+name+'</h1><p>'+('Keep the original commercial question as one brief transition. The photograph returns immediately afterward.' if option=='a' else 'Cut directly from hero to photography. Let the category caption and original cards carry commercial meaning.')+'</p></div><div class="storygrid">'
 body+=beat(1,'A photographic window','<div class="loader-replica"><img src="assets/'+asset[3]+'"></div>','The existing loader and handoff remain unchanged. This frame represents the window, not a new loader design.','PROTECTED SEQUENCE / REPRESENTATIVE STILL')
 body+=beat(2,'The place arrives','<img src="images/hero-desktop-en.jpg">','Original image, headline and boundary behavior. One invitation in the cream margin; on mobile it sits below the photograph.')
 if option=='a':body+=beat(3,'The reason to choose','<img src="images/bridge-short-desktop.png">','Why your property? Preserve the commercial question, condensed to 560 px desktop / 480 px mobile. No new CTA or selector.')
 else:body+=beat(3,'A direct photographic cut',film,'No standalone comparison. This preserves the strongest atmospheric continuity, but the owner’s problem is less explicit.')
 if option=='a':body+=beat(4,'Inhabit the frame',film,'Nine existing images: reflection, orchid, lounge, terrace, guests, table tennis, loungers, golden beach, leaves. Protect gallery mechanics.')
 body+=beat(5 if option=='a' else 4,'Attention becomes a choice','<img src="images/cards-desktop.png">','The original Observe / Decide / Create deck. Keep its spatial selection; add no duplicate exercise.','PROTECTED COMPONENT / CURRENT STILL')
 body+=beat(6 if option=='a' else 5,'A human ending','<img src="images/dear-desktop.png">','Dear EXIF stays the quiet coda. No promotional section before it. Navigation and the founder’s letter remain protected.','PROTECTED COMPONENT / CURRENT STILL')
 if option=='b':body+='<article class="beat"><div class="visual"><div style="padding:40px;font:32px/1.25 Georgia;color:#1c362a">The photograph leads.<br><br>The owner’s question comes later.</div></div><div class="copy"><span class="tiny">REVIEW NOTE / NOT AN EXTRA HOMEPAGE SECTION</span><h2>The commercial tradeoff</h2><p>The category caption and original cards carry relevance. No relocation of the original comparison is assumed.</p></div></article>'
 body+='</div><div class="storyfoot">'+('Recommended: A. It keeps the connection between the emotional arrival and an owner’s reason to engage EXIF, without retaining the original comparison’s long delay.' if option=='a' else 'B is the useful counter-test. It makes the photographic flow stronger, but risks letting the gallery read as a photographer’s portfolio before the business question becomes explicit.')+' These are storyboard stills; they do not demonstrate new animation or a working page.</div></main>'
 page('storyboard-'+option+'.html',body,'Homepage storyboard '+option.upper())
 for mode in ['desktop','mobile']:
  body='<main class="home-static"><div class="mock-label">MOCKUP / HOMEPAGE '+option.upper()+' / '+name+' / NOT WORKING UI</div><img src="images/hero-'+mode+'-en.png">'
  if option=='a':body+='<img class="bridgeimg" src="images/bridge-short-'+mode+'.png">'
  body+='<img src="images/gallery-edit-'+mode+'.png"><img src="images/cards-'+mode+'.png"><img src="images/dear-'+mode+'.png"></main>'
  page('homepage-'+option+'-'+mode+'.html',body,'Static homepage '+option.upper()+' '+mode)
hero=review('Hero — exact mobile compositions')+'<div class="hero-board"><h1>Let the photograph keep the first screen.</h1><div class="two"><img src="images/hero-mobile-en.png"><img src="images/hero-mobile-es.png"></div><p>390 × 844 photographic viewport, then a 136 px cream invitation strip. The original photograph and headline remain unchanged in both languages. The CTA is deliberately below the first screen; no copy is pushed into the photographic field. The span shown here is not an active link.</p></div>'
page('hero-mobile-board.html',hero,'Hero — mobile compositions')
comparison=review('Bridge — controlled comparison')+'<main class="comparison-board"><h1>Keep the question. Remove the long delay.</h1><div class="comparison-columns">'
for key,title,desc in [('original','Protected original','Commercial relevance is explicit, but the comparison occupies 2,514 desktop / 1,616 mobile pixels before the gallery.'),('a','A / One brief bridge','Same purpose, four original statements. Proposed footprint: 560 desktop / 480 mobile pixels. No new CTA.'),('b','B / Direct cut','Photography returns fastest. The category caption names the service, but the owner’s choice problem is deferred.')]:
 comparison+='<section><h2>'+title+'</h2><div class="testviewport"><div class="hero-tail"><img src="images/hero-mobile-en.png"></div>'
 if key=='original':comparison+='<img src="images/original-comparison-mobile.png">'
