index=review('Visual direction packet')+'<main class="review-index"><h1>Visual direction review / 02</h1><p>Static compositions only. Website source and protected interactions remain unchanged. Open the visual boards below; the concise review notes are in README.md.</p><ul>'
for f,label in [('storyboard-a.html','Homepage A — recommended compact bridge'),('storyboard-b.html','Homepage B — direct photographic cut'),('bridge-comparison.html','Original / compact / omitted comparison'),('hero-mobile-board.html','Exact mobile hero in English and Spanish'),('gallery-sources.html','All 13 photographs and editorial decisions'),('gallery-edit.html','Proposed nine-image sequence'),('approach.html','Approach — viewing room'),('what-we-do.html','What We Do — working table'),('homepage-a-mobile.html','Full mobile pacing montage A'),('homepage-b-mobile.html','Full mobile pacing montage B')]:index+='<li><a href="'+f+'">'+label+'</a></li>'
